AgentHPOBench evaluates whether an autonomous agent can improve executable machine learning experiments through sequential hyperparameter interventions. The benchmark contains 30 repository-level tasks spanning language, vision, time series, graph learning, reinforcement learning, generative modeling, and structured learning.

Each task provides:

- a validated baseline configuration;
- a target metric and paper or repository reference;
- a constrained intervention space derived from official repository resources;
- an execution adapter for a baseline run and five sequential interventions;
- complete configuration, metric, log, and decision provenance in the result JSON.

def best_trial(task: str, history: list[dict[str, Any]]) -> dict[str, Any]:
    candidates = history[1:] if len(history) > 1 else history
    reverse = direction(task) == "higher_is_better"
    return sorted(candidates, key=lambda item: metric_value(task, item)[0] if metric_value(task, item)[0] is not None else (-1e99 if reverse else 1e99), reverse=reverse)[0]


def prompt_history_item(task: str, item: dict[str, Any]) -> dict[str, Any]:
    value, metric = metric_value(task, item)
    return {
        "trial": item.get("trial"),
        "kind": item.get("kind"),
        "config": item.get("config"),
        "metric": metric,
        "value": value,
    }

def metric_value(task: str, obj: Any) -> tuple[float | None, str | None]:
    if isinstance(obj, dict):
        for key in METRIC_KEYS.get(task, []):
            val = as_number(obj.get(key))
            if val is not None:
                return val, key
        for key in ("metrics", "final_metrics", "baseline_metrics", "score", "final", "agent_metrics"):
            val, metric = metric_value(task, obj.get(key))
            if val is not None:
                return val, metric
        for key, value in obj.items():
            if isinstance(key, str) and any(token in key.lower() for token in ["accuracy", "auc", "mse", "rmse", "mae", "wape", "score", "rel"]):
                val = as_number(value)
                if val is not None:
                    return val, key
    return None, None

def call_run_eval(module: Any, task: str, kind: str, trial: int, config: dict[str, Any]) -> dict[str, Any]:
    sig = inspect.signature(module.run_eval)
    params = list(sig.parameters)
    if params == ["kind", "trial_idx", "config", "limit"]:
        limit = getattr(module, "FINAL_LIMIT", getattr(module, "PROXY_LIMIT", 0))
        return module.run_eval(kind, trial, config, limit)
    if params == ["kind", "trial_idx", "config", "max_windows"]:
        return module.run_eval(kind, trial, config, 0)
    return module.run_eval(kind, trial, config)


def call_decide(module: Any, task: str, history: list[dict[str, Any]], current: dict[str, Any], baseline: float, step: int) -> dict[str, Any]:
    fn = module.decide_with_qwen
    params = list(inspect.signature(fn).parameters)
    if params == ["history", "config", "budget_remaining", "decision_number"]:
        try:
            return fn(history, current, TARGET_INTERVENTIONS - step + 1, step - 1)
        except Exception:
            if hasattr(module, "fallback_decision"):
                return module.fallback_decision(history, current, step - 1)
            raise
    if params == ["history", "current", "baseline"]:
        return fn(history, current, baseline)
    if params == ["history", "current", "baseline", "decision_number", "total_interventions"]:
        return fn(history, current, baseline, step - 1, TARGET_INTERVENTIONS)
    if params == ["history", "current", "budget_baseline"]:
        return fn(history, current, baseline)
    if params == ["history", "current"]:
        return fn(history, current)
    if params == ["history", "baseline"]:
        return fn(history, baseline)
    raise RuntimeError(f"unsupported decide signature for {task}: {params}")

def intervention_trace(
    payload: dict[str, Any], expected_interventions: int = 5
) -> tuple[list[dict[str, Any]], str]:
    """Return an exact baseline-plus-intervention trace and its schema."""
    expected_length = expected_interventions + 1
    history = payload.get("history")
    if isinstance(history, list):
        explicit = [
            item
            for item in history
            if isinstance(item, dict)
            and (
                item.get("kind") == "baseline"
                or str(item.get("kind", "")).startswith("intervention_")
            )
        ]
        if len(explicit) == expected_length:
            return explicit, "explicit_history"
        if len(history) == expected_length and all(
            isinstance(item, dict) for item in history
        ):
            return history, "native_history"
    chunks = payload.get("chunk_summaries")
    if isinstance(chunks, list) and len(chunks) == expected_length and all(
        isinstance(item, dict) for item in chunks
    ):
        return chunks, "chunk_summaries"
    raise ValueError(
        f"expected baseline plus {expected_interventions} intervention trace"
    )


def decision_count(
    payload: dict[str, Any],
    trace: list[dict[str, Any]],
    expected_interventions: int = 5,
) -> tuple[int, bool]:
    """Return the recorded decision count and whether it was inferred."""
    for key in DECISION_CONTAINERS:
        value = payload.get(key)
        if isinstance(value, list):
            return len(value), False
    for key in ("decisions_made", "agent_decisions_made", "strict_decision_count"):
        value = payload.get(key)
        if isinstance(value, bool):
            continue
        if isinstance(value, (int, float)):
            return int(value), False
        if isinstance(value, str):
            try:
                return int(float(value.strip())), False
            except ValueError:
                pass
    if (
        len(trace) == expected_interventions + 1
        and payload.get("strict_serial_protocol") is True
    ):
        return expected_interventions, True
    return 0, False

def result_artifact_roots(
    result_path: Path, payload: dict[str, Any]
) -> list[Path]:
    task_dir = result_path.parent
    roots: list[Path] = []
    for key in RUN_DIRECTORY_KEYS:
        value = payload.get(key)
        if not isinstance(value, str) or not value.strip():
            continue
        path = Path(value)
        candidate = path if path.is_absolute() else task_dir / path
        if candidate.exists():
            roots.append(candidate)
    run_id = payload.get("run_id")
    if isinstance(run_id, str) and run_id.strip():
        candidate = task_dir / "runs" / run_id
        if candidate.exists():
            roots.append(candidate)
    if not roots:
        roots.append(task_dir)
    return list(dict.fromkeys(path.resolve() for path in roots))


def _artifact_files(roots: list[Path], patterns: tuple[str, ...]) -> list[Path]:
    files = {
        path.resolve()
        for root in roots
        for pattern in patterns
        for path in root.rglob(pattern)
        if path.is_file()
    }
    return sorted(files)


def raw_response_files(result_path: Path, payload: dict[str, Any]) -> list[Path]:
    """Locate current-run local-model response artifacts."""
    return _artifact_files(
        result_artifact_roots(result_path, payload), RAW_RESPONSE_PATTERNS
    )


def embedded_raw_responses(payload: dict[str, Any]) -> list[str]:
    """Return at most one explicit raw model response per recorded decision."""
    decisions: list[Any] = []
    for key in DECISION_CONTAINERS:
        value = payload.get(key)
        if isinstance(value, list):
            decisions = value
            break
    responses: list[str] = []
    for decision in decisions:
        if not isinstance(decision, dict):
            continue
        containers = [decision]
        metadata = decision.get("metadata")
        if isinstance(metadata, dict):
            containers.append(metadata)
        response = next(
            (
                container[key].strip()
                for container in containers
                for key in EMBEDDED_RAW_RESPONSE_KEYS
                if isinstance(container.get(key), str) and container[key].strip()
            ),
            None,
        )
        if (
            response is None
            and isinstance(metadata, dict)
            and metadata.get("direct_prompt") is True
            and isinstance(decision.get("reasoning"), str)
            and decision["reasoning"].strip()
        ):
            # Older direct-generation adapters stored the exact decoded output
            # in reasoning and marked that schema explicitly.
            response = decision["reasoning"].strip()
        if response is not None:
            responses.append(response)
    return responses


def raw_response_count(result_path: Path, payload: dict[str, Any]) -> int:
    """Count logical responses without double-counting JSON and file artifacts."""
    embedded_count = len(embedded_raw_responses(payload))
    recorded_decisions = next(
        (
            len(payload[key])
            for key in DECISION_CONTAINERS
            if isinstance(payload.get(key), list)
        ),
        0,
    )
    if recorded_decisions and embedded_count == recorded_decisions:
        return embedded_count
    file_count = sum(
        path.stat().st_size > 0 for path in raw_response_files(result_path, payload)
    )
    return max(embedded_count, file_count)


def artifact_integrity_issues(
    result_path: Path, payload: dict[str, Any]
) -> list[str]:
    """Return current-run agent artifact failures omitted from result JSON."""
    roots = result_artifact_roots(result_path, payload)
    error_files = [
        path
        for path in _artifact_files(roots, ERROR_ARTIFACT_PATTERNS)
        if path.stat().st_size > 0
    ]
    raw_files = _artifact_files(roots, RAW_RESPONSE_PATTERNS)
    issues = []
    if error_files:
        issues.append(f"nonempty model-error files: {len(error_files)}")
    empty_raw = sum(path.stat().st_size == 0 for path in raw_files)
    if empty_raw:
        issues.append(f"empty raw-response files: {empty_raw}")
    return issues

def protocol_integrity_issues(
    payload: dict[str, Any],
    *,
    expected_interventions: int = 5,
    expected_seed: int | None = None,
    require_seed: bool = True,
) -> list[str]:
    """Validate the shared sequential protocol for one final result."""
    issues: list[str] = []
    trace: list[dict[str, Any]] = []
    try:
        trace, _ = intervention_trace(payload, expected_interventions)
    except ValueError as exc:
        issues.append(str(exc))

    decisions, _ = decision_count(payload, trace, expected_interventions)
    if decisions != expected_interventions:
        issues.append(
            f"expected {expected_interventions} decisions, got {decisions}"
        )

    fallbacks = fallback_count(payload)
    if fallbacks:
        issues.append(f"fallback decisions: {fallbacks}")

    for key in ("error", "task_error", "execution_error", "failure_reason"):
        if _has_nonempty_value(payload.get(key)):
            issues.append(f"nonempty task-level {key}")
    for key in ("success", "agent_success"):
        if key in payload and payload[key] is False:
            issues.append(f"{key}=false")

    replicate_seed = payload.get("replicate_seed")
    if expected_seed is not None:
        try:
            recorded_seed = int(replicate_seed)
        except (TypeError, ValueError):
            if require_seed:
                issues.append("missing or invalid replicate_seed")
        else:
            if recorded_seed != expected_seed:
                issues.append(
                    f"replicate seed mismatch: expected {expected_seed}, got {recorded_seed}"
                )
    return issues


def local_model_integrity_issues(
    result_path: Path,
    payload: dict[str, Any],
    *,
    expected_interventions: int = 5,
    expected_seed: int | None = None,
    expected_model: str | None = None,
    require_seed: bool = True,
    require_raw_responses: bool = True,
    check_artifacts: bool = True,
) -> list[str]:
    """Validate the protocol and local-model provenance for one final result."""
    issues = protocol_integrity_issues(
        payload,
        expected_interventions=expected_interventions,
        expected_seed=expected_seed,
        require_seed=require_seed,
    )
    if check_artifacts:
        issues.extend(artifact_integrity_issues(result_path, payload))
    if require_raw_responses:
        nonempty_raw = raw_response_count(result_path, payload)
        if nonempty_raw != expected_interventions:
            issues.append(
                f"expected {expected_interventions} nonempty raw responses, got {nonempty_raw}"
            )

    if expected_model and not model_provenance_matches(
        result_path, payload, expected_model
    ):
        issues.append(f"configured model provenance not found: {expected_model}")
    return issues

def _narrow_space(search_space: dict[str, Any], base_config: dict[str, Any]) -> dict[str, Any]:
    keys = list(search_space)
    priority = {name: index for index, name in enumerate(CORE_PRIORITY)}
    ranked = sorted(
        enumerate(keys),
        key=lambda item: (priority.get(item[1].lower(), len(priority) + item[0]), item[0]),
    )
    tunable = {key for _, key in ranked[: min(3, len(ranked))]}
    result: dict[str, Any] = {}
    for key, spec in search_space.items():
        values = _choices(spec)
        if not values:
            result[key] = copy.deepcopy(spec)
            continue
        baseline = _baseline_choice(values, base_config.get(key))
        if key not in tunable or len(values) == 1:
            narrowed = [baseline]
        else:
            alternatives = [value for value in values if not _same(value, baseline)]
            nearest = min(alternatives, key=lambda value: _distance(value, baseline)) if alternatives else baseline
            narrowed = _dedupe([baseline, nearest])
        result[key] = _wrap_like(spec, narrowed)
    return result

def _wide_space(search_space: dict[str, Any]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, spec in search_space.items():
        values = _choices(spec)
        additions = _midpoint_additions(key, values) + _range_additions(key, values)
        result[key] = _wrap_like(spec, _dedupe(values + additions))
    return result


def apply_space_variant(
    task_name: str,
    search_space: dict[str, Any],
    base_config: dict[str, Any],
    variant: str,
) -> dict[str, Any]:
    del task_name
    normalized = str(variant or "original").strip().lower()
    if normalized in {"original", "orig", "default"}:
        return copy.deepcopy(search_space)
    if normalized == "narrow":
        return _narrow_space(search_space, base_config)
    if normalized in {"wide", "expanded"}:
        return _wide_space(search_space)
    raise ValueError(f"Unknown space variant: {variant!r}")

